export default function WishlistPage() {
  const [wishlistItems, setWishlistItems] = useState<IProduct[]>(initialWishlistItems)
  const [selectedProduct, setSelectedProduct] = useState<{
    _id: string;
    images: string[];
    brandName: string;
    mobile: string;
    genericName: string;
    originalPrice: number;
    discountPrice: number;
    reviews: IReview[];
    productModel?: string;
    href: string;
    color?: string;
    weight?: string;
    description?: string;
  } | null>(null)
  const [isDialogOpen, setIsDialogOpen] = useState(false)

  const removeFromWishlist = (_id: string) => {
    setWishlistItems(wishlistItems.filter((item) => item._id !== _id))
  }

  const openProductDetail = (product: IProduct) => {
    setSelectedProduct({
      _id: product._id,
      images: product.images,
      brandName: product.brandName,
      mobile: product.mobile,
      genericName: product.genericName,
      originalPrice: product.originalPrice,
      discountPrice: product.discountPrice,
      reviews: product.reviews,
      productModel: product.productModel,
      href: `/product/${product._id}`,
      color: product.color,
      weight: product.weight,
      description: product.description,
    })
    setIsDialogOpen(true)
  }

  // Calculate average rating
  const getAverageRating = (reviews: IReview[]) => {
    if (!reviews || reviews.length === 0) return 0
    const total = reviews.reduce((sum, review) => sum + review.rating, 0)
    return Number((total / reviews.length).toFixed(1))
  }

  // Calculate discount percentage
  const getDiscountPercentage = (originalPrice: number, discountPrice: number) => {
    if (originalPrice <= 0) return 0
    return Math.round(((originalPrice - discountPrice) / originalPrice) * 100)
  }

  return (
    <div className="flex min-h-screen flex-col">
      <Navbar />
      <main className="flex-1">
        <div className="container mx-auto py-10 px-4">
          <div className="flex items-center mb-8">
            <Link href="/" className="inline-flex items-center text-sm font-medium">
              <ArrowLeft className="mr-2 h-4 w-4" />
              Continue Shopping
            </Link>
            <h1 className="text-2xl font-bold ml-auto">Your Wishlist</h1>
          </div>

          {wishlistItems.length > 0 ? (
            <div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {wishlistItems.map((item) => (
                  <Card key={item._id} className="overflow-hidden border rounded-lg hover:shadow-md transition-shadow">
                    <div className="relative">
                      <Image
                        src={item.images[0] || "https://placehold.co/300x300/png"}
                        alt={item.genericName}
                        width={300}
                        height={300}
                        className="w-full aspect-square object-cover cursor-pointer"
                        onClick={() => openProductDetail(item)}
                        onError={(e) => {
                          e.currentTarget.src = "https://placehold.co/300x300/png"
                        }}
                      />
                      <div className="absolute top-2 right-2 flex space-x-1">
                        <Button
                          variant="destructive"
                          size="icon"
                          className="h-8 w-8 rounded-full"
                          onClick={() => removeFromWishlist(item._id)}
                        >
                          <Trash2 className="h-4 w-4" />
                          <span className="sr-only">Remove from wishlist</span>
                        </Button>
                      </div>
                    </div>
                    <div className="p-4">
                      <h3
                        className="font-medium text-sm line-clamp-2 mb-2 cursor-pointer hover:text-primary"
                        onClick={() => openProductDetail(item)}
                      >
                        {item.brandName} {item.genericName}
                      </h3>
                      <div className="flex items-center gap-2 mb-3">
                        <span className="text-lg font-bold">${item.discountPrice.toFixed(2)}</span>
                        <span className="text-sm text-muted-foreground line-through">${item.originalPrice.toFixed(2)}</span>
                        <span className="text-sm text-primary">
                          {getDiscountPercentage(item.originalPrice, item.discountPrice)}% off
                        </span>
                      </div>
                      <div className="text-sm text-muted-foreground mb-3">
                        {getAverageRating(item.reviews)} ★ ({item.reviews.length} reviews)
                      </div>
                      <Button className="w-full" size="sm" disabled={item.stock === 0}>
                        <ShoppingCart className="h-4 w-4 mr-2" />
                        {item.stock === 0 ? "Out of Stock" : "Add to Cart"}
                      </Button>
                    </div>
                  </Card>
                ))}
              </div>
            </div>
          ) : (
            <div className="text-center py-12">
              <div className="inline-flex h-20 w-20 items-center justify-center rounded-full bg-muted mb-6">
                <Heart className="h-10 w-10 text-muted-foreground" />
              </div>
              <h2 className="text-2xl font-bold mb-2">Your Wishlist is empty</h2>
              <p className="text-muted-foreground mb-6">
                Looks like you haven&apos;t added any products to your wishlist yet.
              </p>
              <Button asChild>
                <Link href="/collections">Start Shopping</Link>
              </Button>
            </div>
          )}
        </div>
      </main>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-[1000px] p-6">
          {selectedProduct && (
            <ProductDetail
              product={selectedProduct}
              open={isDialogOpen}
              onClose={() => setIsDialogOpen(false)}
            />
          )}
        </DialogContent>
      </Dialog>

      <Footer />
    </div>
  )
}